def search(self, root_node):
    """Adaptive progressive-widening best-first search.

    Strategy
    --------
    1) Maintain a frontier of expandable nodes instead of following a
       single chain.
    2) Expand each node *progressively*: first try one child; only widen to
       additional diverse children if earlier attempts from that node fail.
    3) Use cheap heuristic scoring by default, and invoke expensive LLM
       ranking only when a node has multiple viable siblings and the search
       is still at an important/uncertain decision point.

    This keeps the low-query behavior of DFSDT on easy instances while
    recovering from local mistakes through targeted backtracking.
    """

    def _collect(node):
        """Update global terminal / give-up bookkeeping."""
        if node.is_terminal:
            self.status = 1
            if node not in self.terminal_node:
                self.terminal_node.append(node)
            return
        if node.pruned and node.observation_code == 4:
            if node not in self.give_up_node:
                self.give_up_node.append(node)

    def _heuristic(node):
        """Cheap progress estimate used for frontier ordering."""
        depth = node.get_depth()
        score = -0.12 * depth

        if node.is_terminal:
            return 1e6 - depth
        if node.pruned:
            penalty = 40.0
            if node.observation_code == 4:
                penalty += 8.0
            elif node.observation_code == 1:
                penalty += 4.0
            return -penalty - depth

        node_type = getattr(node, "node_type", "")
        if node_type == "Action Input":
            score += 1.2
            if getattr(node, "observation_code", 0) == 0:
                score += 1.3
            if getattr(node, "observation", ""):
                obs = node.observation.lower()
                if "error" in obs or "invalid" in obs or "exception" in obs:
                    score -= 0.7
                else:
                    score += 0.3
        elif node_type == "Thought":
            score += 0.2

        score -= 0.55 * getattr(node, "local_failures", 0)
        score -= 0.18 * getattr(node, "expand_trials", 0)
        score += 0.08 * max(0, self.single_chain_max_step - depth)
        return score

    def _remaining_expansions(node):
        return max(0, self.tree_beam_size - getattr(node, "expand_trials", 0))

    def _push(frontier, node):
        if node is None:
            return
        if node.is_terminal or node.pruned:
            return
        if node.get_depth() >= self.single_chain_max_step:
            node.pruned = True
            return
        if _remaining_expansions(node) <= 0 and len(node.children) > 0:
            return
        if node not in frontier:
            frontier.append(node)

    frontier = [root_node]
    setattr(root_node, "expand_trials", 0)
    setattr(root_node, "local_failures", 0)

    while frontier:
        if self.query_count >= self.max_query_count:
            break
        if len(self.terminal_node) >= self.answer_count:
            break

        frontier.sort(key=_heuristic, reverse=True)
        now_node = frontier.pop(0)

        if now_node.is_terminal or now_node.pruned:
            _collect(now_node)
            continue

        if now_node.get_depth() >= self.single_chain_max_step:
            now_node.pruned = True
            continue

        trials_done = getattr(now_node, "expand_trials", 0)
        failures = getattr(now_node, "local_failures", 0)
        remaining = self.tree_beam_size - trials_done
        if remaining <= 0:
            continue

        # Progressive widening: start narrow, widen only after failures.
        width = 1 if trials_done == 0 else min(remaining, 1 + failures)
        if self.max_query_count - self.query_count <= 2:
            width = 1

        new_candidates = []
        viable_siblings = []

        for _ in range(width):
            if self.query_count >= self.max_query_count:
                break
            if getattr(now_node, "expand_trials", 0) >= self.tree_beam_size:
                break

            added_diversity = self._add_diversity_prompt(now_node)
            new_leaves = self._step(now_node)
            now_node.expand_trials = getattr(now_node, "expand_trials", 0) + 1

            if added_diversity and len(now_node.messages) > 0:
                now_node.messages[-1]["valid"] = False

            if not new_leaves:
                break

            leaf = new_leaves[-1]
            setattr(leaf, "expand_trials", getattr(leaf, "expand_trials", 0))
            setattr(leaf, "local_failures", getattr(leaf, "local_failures", 0))
            _collect(leaf)

            if leaf.get_depth() >= self.single_chain_max_step and not leaf.is_terminal:
                leaf.pruned = True

            if leaf.pruned and not leaf.is_terminal:
                now_node.local_failures = getattr(now_node, "local_failures", 0) + 1
            else:
                new_candidates.append(leaf)

        if len(self.terminal_node) >= self.answer_count:
            break

        for child in now_node.children:
            temp = child
            while (
                not temp.is_terminal
                and not temp.pruned
                and temp.node_type != "Action Input"
                and len(temp.children) > 0
            ):
                temp = temp.children[0]
            if not temp.pruned and not temp.is_terminal and temp.get_depth() < self.single_chain_max_step:
                viable_siblings.append(temp)

        # Use ranking only for uncertain branching points: multiple viable
        # siblings, enough budget left, and shallow/high-impact decisions or
