        need_rank = (
            len(viable_siblings) > 1
            and self.max_query_count - self.query_count > max(6, self.tree_beam_size)
            and (now_node.get_depth() <= 4 or getattr(now_node, "local_failures", 0) > 0)
        )
        if need_rank:
            scores = self._rank_nodes(viable_siblings)
            for cand, score in zip(viable_siblings, scores):
                cand.prior_score = score
        else:
            for cand in viable_siblings:
                cand.prior_score = 0.0

        ordered = sorted(
            viable_siblings,
            key=lambda x: getattr(x, "prior_score", 0.0) + _heuristic(x),
            reverse=True,
        )

        for cand in ordered:
            _push(frontier, cand)

        # If this node produced no viable continuation but still has unused
        # beam budget, revisit it later for another diverse attempt.
        if not ordered and _remaining_expansions(now_node) > 0 and not now_node.pruned:
            _push(frontier, now_node)

        # If it produced some children and still has budget left, keep a
        # low-priority chance to widen later after other branches report back.
        elif ordered and _remaining_expansions(now_node) > 0 and getattr(now_node, "local_failures", 0) > 0:
            _push(frontier, now_node)

